export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed ?? 4;
  const g = inputs.gravity ?? 9.8;

  const tTop = u / g;
  const yTop = (u * u) / (2 * g);
  const duration = (2 * u) / g;
  const clampedT = Math.max(0, Math.min(time, duration));

  // Tossed ball dynamics
  const yToss = u * clampedT - 0.5 * g * clampedT * clampedT;
  const vToss = u - g * clampedT;
  const aToss = -g;

  // Dropped ball dynamics
  let yDrop = yTop;
  let vDrop = 0;
  let aDrop = 0;
  let dropState = "Held in place";

  if (clampedT >= tTop) {
    const dt = clampedT - tTop;
    yDrop = yTop - 0.5 * g * dt * dt;
    vDrop = -g * dt;
    aDrop = -g;
    if (Math.abs(dt) < 0.001) {
      dropState = "Just released";
    } else {
      dropState = "Falling together";
    }
  }

  let tossState = "Rising";
  if (clampedT === 0) {
    tossState = "At launch";
  } else if (Math.abs(clampedT - tTop) < 0.001) {
    tossState = "At the top";
  } else if (clampedT > tTop) {
    if (clampedT >= duration - 0.001) {
      tossState = "At launch height";
      if (clampedT >= tTop) dropState = "At launch height";
    } else {
      tossState = "Falling";
    }
  }

  // Geometry mapping
  const laneY = 50;
  const laneH = 340;
  const laneW = 270;
  const tossX = 30;
  const dropX = 340;
  const originY = laneY + laneH - 40; // Height = 0 m
  const scaleY = 120; // 120 px per m

  const pyToss = originY - yToss * scaleY;
  const pyDrop = originY - yDrop * scaleY;
  const pyTop = originY - yTop * scaleY;

  const pxToss = tossX + laneW / 2;
  const pxDrop = dropX + laneW / 2;

  const objects = [];

  // Lanes
  const tossPanel = sdk.panel({
    id: "lane.toss",
    x: tossX,
    y: laneY,
    w: laneW,
    h: laneH,
    title: "Toss Lane",
    state: tossState
  });
  const dropPanel = sdk.panel({
    id: "lane.drop",
    x: dropX,
    y: laneY,
    w: laneW,
    h: laneH,
    title: "Drop Lane",
    state: dropState
  });
  objects.push(...tossPanel, ...dropPanel);

  // Axes inside lanes
  objects.push(
    sdk.axis("axis.toss", {
      x: tossX + 45,
      y: originY,
      length: 260,
      orientation: "y",
      min: 0,
      max: 2.2,
      ticks: [0, 0.5, 1.0, 1.5, 2.0],
      label: "Height",
      unit: "m"
    }),
    sdk.axis("axis.drop", {
      x: dropX + 45,
      y: originY,
      length: 260,
      orientation: "y",
      min: 0,
      max: 2.2,
      ticks: [0, 0.5, 1.0, 1.5, 2.0],
      label: "Height",
      unit: "m"
    })
  );

  // Faint ghost circle at starting apex for drop lane
  if (clampedT > tTop) {
    objects.push({
      kind: "circle",
      id: "ghost.drop",
      x: pxDrop,
      y: pyTop,
      w: 24,
      opacity: 0.35
    });
  }

  // Release Gate
  const gateOpen = clampedT >= tTop;
  objects.push(...sdk.gate("gate", pxDrop, pyTop, { open: gateOpen, label: "Gate" }));

  // Balls
  objects.push(
    sdk.circle("ball.toss", pxToss, pyToss, 28),
    sdk.circle("ball.drop", pxDrop, pyDrop, 28)
  );

  // Vectors - Toss
  const vScale = 15;
  const aScale = 5;

  objects.push(
    ...sdk.vector("vec.v.toss", { x: pxToss - 22, y: pyToss }, {
      value: vToss,
      direction: "up",
      scale: vScale,
      label: `v = ${vToss.toFixed(2)}`,
      role: "output"
    }),
    ...sdk.vector("vec.a.toss", { x: pxToss + 22, y: pyToss }, {
      value: aToss,
      direction: "up",
      scale: aScale,
      label: `a = ${aToss.toFixed(1)}`,
      role: "warning"
    })
  );

  // Vectors - Drop
  objects.push(
    ...sdk.vector("vec.v.drop", { x: pxDrop - 22, y: pyDrop }, {
      value: vDrop,
      direction: "up",
      scale: vScale,
      label: `v = ${vDrop.toFixed(2)}`,
      role: "output"
    }),
    ...sdk.vector("vec.a.drop", { x: pxDrop + 22, y: pyDrop }, {
      value: aDrop,
      direction: "up",
      scale: aScale,
      label: `a = ${aDrop.toFixed(1)}`,
      role: "warning"
    })
  );

  // Callouts
  objects.push(
    ...sdk.callout(pxToss + 40, pyToss - 14, [
      `v: ${vToss.toFixed(2)} m/s`,
      `a: ${aToss.toFixed(1)} m/s²`
    ], { id: "callout.toss" }),
    ...sdk.callout(pxDrop + 40, pyDrop - 14, [
      `v: ${vDrop.toFixed(2)} m/s`,
      `a: ${aDrop.toFixed(1)} m/s²`
    ], { id: "callout.drop" })
  );

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: "tossedVelocity", value: vToss },
        { id: "tossedAcceleration", value: aToss },
        { id: "dropVelocity", value: vDrop },
        { id: "dropAcceleration", value: aDrop }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      apexTime: tTop,
      apexHeight: yTop,
      tossedVelocity: vToss,
      tossedAcceleration: aToss,
      tossedHeight: yToss,
      dropVelocity: vDrop,
      dropAcceleration: aDrop,
      dropHeight: yDrop
    }
  };
}
